-- ============================================
-- PARENTESCOS: relación de cada persona con el titular del expediente.
-- ES_TITULAR marca el parentesco "TITULAR" (uno solo por expediente).
-- ORDEN: orden de aparición dentro del grupo familiar.
-- ============================================
CREATE TABLE IF NOT EXISTS "PARENTESCOS" (
    "ID_PARENTESCO" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_PARENTESCOS" PRIMARY KEY,
    "NOMBRE" VARCHAR(50) NOT NULL CONSTRAINT "UQ_PARENTESCOS_NOMBRE" UNIQUE,
    "ES_TITULAR" BOOLEAN NOT NULL DEFAULT FALSE,
    "ORDEN" INT NOT NULL DEFAULT 50,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);
